import bpy

class ANIM_OT_clean_unused_fcurves(bpy.types.Operator):
    bl_idname = "anim.clean_unused_fcurves"
    bl_label = "Clean Unselected Bone FCurves"
    bl_description = "Remove FCurves of unselected bones from the current action"
    bl_options = {'REGISTER', 'UNDO'}

    def execute(self, context):
        obj = context.object
        if not obj or obj.type != 'ARMATURE':
            self.report({'WARNING'}, "Please select an armature object")
            return {'CANCELLED'}

        if not obj.animation_data or not obj.animation_data.action:
            self.report({'WARNING'}, "No action found on the armature")
            return {'CANCELLED'}

        if not context.selected_pose_bones:
            self.report({'WARNING'}, "No bones selected in Pose Mode")
            return {'CANCELLED'}

        action = obj.animation_data.action
        selected_bones = {bone.name for bone in context.selected_pose_bones}
        to_remove = []

        for fcurve in action.fcurves:
            path = fcurve.data_path
            if path.startswith('pose.bones["'):
                bone_name = path.split('"')[1]
                if bone_name not in selected_bones:
                    to_remove.append(fcurve)

        for fc in to_remove:
            action.fcurves.remove(fc)

        self.report({'INFO'}, f" Action '{action.name}': Removed {len(to_remove)} unselected bone FCurves")
        return {'FINISHED'}

class ANIM_PT_cleanup_panel(bpy.types.Panel):
    bl_label = "Animation Cleanup Tools"
    bl_idname = "ANIM_PT_cleanup_panel"
    bl_space_type = 'VIEW_3D'
    bl_region_type = 'UI'
    bl_category = 'Animation Tools'

    def draw(self, context):
        layout = self.layout
        obj = context.object
        action = obj.animation_data.action if obj and obj.animation_data else None

        if action:
            layout.label(text=f"Current Action: {action.name}", icon="ACTION")
        else:
            layout.label(text="No action found", icon="ERROR")

        layout.operator("anim.clean_unused_fcurves", icon="TRASH")

classes = [ANIM_OT_clean_unused_fcurves, ANIM_PT_cleanup_panel]

def register():
    for cls in classes:
        bpy.utils.register_class(cls)

def unregister():
    for cls in reversed(classes):
        bpy.utils.unregister_class(cls)

if __name__ == "__main__":
    register()

import bpy

threshold = 0.001
obj = bpy.context.object

removed_count = 0  # 初始化计数器

if obj and obj.type == 'MESH':
    if obj.vertex_groups:
        bpy.ops.object.mode_set(mode='OBJECT')
        verts = obj.data.vertices

        for v in verts:
            weights_to_remove = []
            for g in v.groups:
                if g.weight < threshold:
                    weights_to_remove.append(g.group)
            for group_index in weights_to_remove:
                obj.vertex_groups[group_index].remove([v.index])
                removed_count += 1  # 每次移除+1

        print(f"完成：已删除 {removed_count} 个小于 {threshold} 的权重。")
    else:
        print("物体没有权重组。")
else:
    print("请选择一个网格对象。")

import bpy
import math

default_transform = {
    "location": (0, -5.716, 4.88852),
    "rotation": (-90, 0, 0),
    "scale": 3.125
}

wind_settings = {
    "IDLE": {
        "label": "Idle Wind",
        "strength_expr": "15+8*sin(frame/11.9)", 
        "use_driver": True,
        "action": "Idle-E",
        **default_transform,
    },
    "WALK": {
        "label": "Walk Wind",
        "use_driver": False,
        "strength_value": 16,
        "action": "Walk-E",
        **default_transform,
    },
    "RUN": {
        "label": "Run Wind",
        "use_driver": False,
        "strength_value": 20,
        "action": "Run-E",
        **default_transform,
    }
}

# Generate enum
def get_enum_items():
    items = []
    for key, value in wind_settings.items():
        desc = value.get("strength_expr", str(value.get("strength_value", "")))
        items.append((key, value["label"], desc))
    return items

# Operator: Apply wind settings
class WIND_ANIMATOR_OT_ApplyWind(bpy.types.Operator):
    bl_idname = "object.apply_wind_animation"
    bl_label = "Apply Wind"

    wind_type: bpy.props.EnumProperty(
        name="Wind Type",
        items=get_enum_items()
    )

    def execute(self, context):
        obj = context.scene.simple_picker.target_object

        if not obj:
            self.report({'WARNING'}, "请先选择一个风的目标对象！")
            return {'CANCELLED'}

        if not obj.field or obj.field.type != 'WIND':
            self.report({'WARNING'}, f"{obj.name} 不是风力对象！")
            return {'CANCELLED'}

        settings = wind_settings[self.wind_type]

        # Wind strength
        if obj.field and obj.field.type == 'WIND':
            obj.field.driver_remove("strength")
            if settings["use_driver"]:
                driver = obj.field.driver_add("strength").driver
                driver.expression = settings["strength_expr"]
            else:
                obj.field.strength = settings["strength_value"]
        else:
            self.report({'INFO'}, f"{obj.name} 不是风力对象，跳过风力设置。")

        # Transform
        obj.location = settings.get("location", obj.location)
        rot = settings.get("rotation", obj.rotation_euler)
        obj.rotation_euler = tuple(math.radians(a) for a in rot)  # convert to radians
        scale = settings.get("scale", obj.scale)
        obj.scale = (scale, scale, scale)

        # Animation actions
        armature = bpy.data.objects.get("Armature_Elaina")
        action_name = settings.get("action")
        if armature and action_name:
            action = bpy.data.actions.get(action_name)
            if action:
                if armature.animation_data is None:
                    armature.animation_data_create()
                armature.animation_data.action = action
                context.scene.frame_start = int(action.frame_range[0])
                context.scene.frame_end = int(action.frame_range[1])
                context.scene.frame_current = int(action.frame_range[0])

        return {'FINISHED'}

# Property group to select target wind object
class SimplePickerProperties(bpy.types.PropertyGroup):
    target_object: bpy.props.PointerProperty(type=bpy.types.Object)

# UI Panel in the 3D view
class WIND_PT_Panel(bpy.types.Panel):
    bl_label = "Wind Control"
    bl_idname = "WIND_PT_Panel"
    bl_space_type = 'VIEW_3D'
    bl_region_type = 'UI'
    bl_category = 'Pose'

    def draw(self, context):
        layout = self.layout
        props = context.scene.simple_picker

        for wind_key, wind_data in wind_settings.items():
            label = wind_data["label"]
            op = layout.operator("object.apply_wind_animation", text=label)
            op.wind_type = wind_key

        layout.separator()
        layout.prop(props, "target_object", text="Wind")

# Registration
classes = [WIND_ANIMATOR_OT_ApplyWind, WIND_PT_Panel, SimplePickerProperties]

def register():
    for cls in classes:
        bpy.utils.register_class(cls)
    bpy.types.Scene.simple_picker = bpy.props.PointerProperty(type=SimplePickerProperties)

def unregister():
    for cls in reversed(classes):
        bpy.utils.unregister_class(cls)
    del bpy.types.Scene.simple_picker

if __name__ == "__main__":
    register()
